import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Entry 460 | Dragon Ball · Saiyan Setting: The Predatory Essence of a Warrior Race","description":"","frontmatter":{"title":"Entry 460 | Dragon Ball · Saiyan Setting: The Predatory Essence of a Warrior Race","no":460,"module":2,"tags":["Myriad-Realms Benchmark","Dragon Ball","Saiyan","Warrior Race","Predatory Essence","Anti-Predation"],"related":["04-Anti-Predation Core Thesis","19-Cultivation Ethics and Boundaries","57-Dark-Replacement Body Origin and Essence"]},"headers":[],"relativePath":"en/0460_模块2-龙珠-赛亚人设定-战斗民族的掠夺本质.md","filePath":"en/0460_模块2-龙珠-赛亚人设定-战斗民族的掠夺本质.md"}'),o={name:"en/0460_模块2-龙珠-赛亚人设定-战斗民族的掠夺本质.md"};function r(s,e,l,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="entry-460-dragon-ball-·-saiyan-setting-the-predatory-essence-of-a-warrior-race" tabindex="-1">Entry 460 | Dragon Ball · Saiyan Setting: The Predatory Essence of a Warrior Race <a class="header-anchor" href="#entry-460-dragon-ball-·-saiyan-setting-the-predatory-essence-of-a-warrior-race" aria-label="Permalink to &quot;Entry 460 | Dragon Ball · Saiyan Setting: The Predatory Essence of a Warrior Race&quot;">​</a></h1><blockquote><p>Module: Module 2 · Myriad-Realms Benchmark Critique Library | Series: Dragon Ball Full Decomposition (Entry 29 · Civilization Analysis 2) | Benchmark base: Documents 04, 19, 57</p></blockquote><h2 id="introduction-a-race-whose-trade-is-conquest" tabindex="-1">Introduction: a race whose trade is conquest <a class="header-anchor" href="#introduction-a-race-whose-trade-is-conquest" aria-label="Permalink to &quot;Introduction: a race whose trade is conquest&quot;">​</a></h2><p>The Saiyans in Dragon Ball worldview are defined as a &quot;warrior race&quot;: they are born with combat power, they love fighting, they are hired by Frieza&#39;s army to conquer planets, they get stronger by near-death revival. This setting writes &quot;predation&quot; into a race&#39;s biological instinct. Though Goku lost his memory and defected, he inherited this racial original sin. This entry takes the <strong>anti-predation axiom</strong> as core, dissecting the Saiyan setting&#39;s predatory essence.</p><p>This entry&#39;s judging base is the six top-level axioms and five mandatory cores, with the law-first axiom as core. The universal equal infinite law: within the Anchor Symbiotic Civilization, all beings inherently possess basic infinite power; the easygoing retain a guaranteed basic infinity and will never be eliminated; strivers and Youth Supremes can superimpose more and higher levels of infinity. Infinite origin is inherent in all, so predation naturally loses its meaning.</p><h2 id="i-energy-level-waste-analysis-of-this-system-s-strong-ones" tabindex="-1">I. &quot;Energy-Level Waste&quot; Analysis of This System&#39;s Strong Ones <a class="header-anchor" href="#i-energy-level-waste-analysis-of-this-system-s-strong-ones" aria-label="Permalink to &quot;I. &quot;Energy-Level Waste&quot; Analysis of This System&#39;s Strong Ones&quot;">​</a></h2><p>Saiyan setting&#39;s energy waste:</p><ul><li><strong>Combat talent wasted on conquest</strong>: Saiyans&#39; innate combat talent hired by Frieza&#39;s army for conquering planets and selling natives — this talent could have been used for Myriad-Ranks co-build</li><li><strong>Near-death gain wasted on killing</strong>: the biologically miraculous &quot;near-death stronger&quot; mechanism, used for the next conquest</li><li><strong>Planet Vegeta civilization wasted</strong>: the Saiyan race could have developed a unique cultivation civilization, but chose to be mercenaries</li></ul><h2 id="ii-why-this-civilization-inevits-historical-regression" tabindex="-1">II. Why This Civilization Inevits Historical Regression <a class="header-anchor" href="#ii-why-this-civilization-inevits-historical-regression" aria-label="Permalink to &quot;II. Why This Civilization Inevits Historical Regression&quot;">​</a></h2><p>How Saiyan predatory essence feeds historical regression:</p><ol><li><strong>Planet Vegeta destroyed by Frieza</strong>: Saiyans were mercenaries for centuries, ultimately silenced by their employer — the predator&#39;s fate</li><li><strong>Survivors are Goku and Vegeta</strong>: two Saiyan survivors, one amnesiac became Earthling, one became villain then reformed — racial civilization completely broken</li><li><strong>Combat instinct unconverted</strong>: Saiyans&#39; instinct to love battle was never converted to &quot;guard Myriad Ranks&quot; duty; always stayed at &quot;find a stronger opponent&quot;</li></ol><h2 id="iii-deep-decomposition-of-the-protagonist-s-predatory-thinking" tabindex="-1">III. Deep Decomposition of the Protagonist&#39;s Predatory Thinking <a class="header-anchor" href="#iii-deep-decomposition-of-the-protagonist-s-predatory-thinking" aria-label="Permalink to &quot;III. Deep Decomposition of the Protagonist&#39;s Predatory Thinking&quot;">​</a></h2><p>Goku&#39;s predatory thinking under Saiyan setting:</p><ul><li><strong>Inheriting racial original sin</strong>: Goku&#39;s combat talent, near-death gain, Super Saiyan transformation route, all inherited from a Saiyan race that lived by predation</li><li><strong>Not reflecting</strong>: Goku never reflects &quot;is my talent from a predatory race&quot;; he defaults &quot;I&#39;m a good person and that&#39;s enough&quot;</li><li><strong>Treating battle as purpose</strong>: Saiyans&#39; instinct to love battle manifests in Goku as &quot;just want to fight the strong&quot; — this instinct never redirected to &quot;guard Myriad Ranks&quot;</li></ul><h2 id="iv-comparison-with-anchor-symbiosis-s-complete-alternative" tabindex="-1">IV. Comparison With Anchor Symbiosis&#39;s Complete Alternative <a class="header-anchor" href="#iv-comparison-with-anchor-symbiosis-s-complete-alternative" aria-label="Permalink to &quot;IV. Comparison With Anchor Symbiosis&#39;s Complete Alternative&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dragon Ball Saiyan Predatory Essence</th><th>Anchor-Symbiosis Alternative</th></tr></thead><tbody><tr><td>Combat talent for conquest</td><td>Combat talent for guarding Myriad-Ranks co-build; anti-predation axiom</td></tr><tr><td>Near-death gain for killing</td><td>Life-cycle system (Doc 012) public; safe conversion, no life bets</td></tr><tr><td>Planet Vegeta civilization broken</td><td>Five Myriad-Ranks genealogies equal; any race has complete civilization lineage</td></tr><tr><td>Combat instinct unconverted</td><td>Plane-Transcendent four-dimensional exam: strength 40 / mind 25 / contribution 20 / responsibility 15</td></tr><tr><td>Racial original sin unpurged</td><td>Saiyan predatory history enshrined for reflection; not as hero narrative</td></tr></tbody></table><h2 id="v-quest-sediment-domain-simulation-review-plan" tabindex="-1">V. Quest Sediment Domain Simulation Review Plan <a class="header-anchor" href="#v-quest-sediment-domain-simulation-review-plan" aria-label="Permalink to &quot;V. Quest Sediment Domain Simulation Review Plan&quot;">​</a></h2><ol><li><strong>Modeling</strong>: Quest Sediment Domain replicates Saiyan race evolution — from being mercenaries to Planet Vegeta&#39;s destruction</li><li><strong>Variables</strong>: inject &quot;if Saiyans chose not to be mercenaries, develop their own cultivation civilization&quot; control</li><li><strong>Observation</strong>: count Saiyan civilization survival years, planets conquered from Myriad Ranks, Saiyan race population</li><li><strong>Review</strong>: output <em>Saiyan Predatory-Essence Cost Report</em>, quantifying &quot;after centuries as mercenaries, what the Saiyans lost&quot;</li></ol><h2 id="vi-setting-self-consistency-retcon-ending-risk-assessment" tabindex="-1">VI. Setting Self-Consistency / Retcon-Ending Risk Assessment <a class="header-anchor" href="#vi-setting-self-consistency-retcon-ending-risk-assessment" aria-label="Permalink to &quot;VI. Setting Self-Consistency / Retcon-Ending Risk Assessment&quot;">​</a></h2><ul><li><strong>Saiyan setting self-consistency: low</strong> (near-death gain rare early; late repeatedly used by Vegeta, Gohan, Trunks)</li><li><strong>Racial setting self-consistency expected: high</strong> (five genealogies equal; Saiyans as one branch have complete civilization lineage)</li><li><strong>Retcon-ending risk: medium</strong> (Super Saiyan from millennium legend devalued to bloodline standard)</li><li><strong>Protagonist uniqueness dependency: high</strong> — Saiyan race&#39;s hero narrative entirely tied to Goku and Vegeta</li></ul><p><strong>Old-new cosmos resource comparison</strong>: old-cosmos resources and Great Dao are finite, inevitably predatory involution; Anchor Symbiosis has everyone inherently possessing infinite origin, predation loses meaning.</p><h2 id="five-core-takeaways" tabindex="-1">Five Core Takeaways <a class="header-anchor" href="#five-core-takeaways" aria-label="Permalink to &quot;Five Core Takeaways&quot;">​</a></h2><ul><li><strong>Anti-energy waste</strong>: combat talent for conquest, not converted to Myriad-Ranks co-build</li><li><strong>Anti-predation</strong>: Saiyans were mercenaries for centuries; predatory history unpurged</li><li><strong>Tang-Luo upper-limit comparison</strong>: Tang Luo at least proactively broke predatory structure; Saiyans are predatory structure itself</li><li><strong>Myriad Races full coverage</strong>: Saiyans as one of Myriad Ranks should be equally included in republicanism, not race-centric</li><li><strong>Hyper-multiverse full openness</strong>: Saiyans&#39; combat instinct should be redirected to multi-path evolution, not single-dimension killing</li><li><strong>Universal equal infinite law</strong>: basic infinite power inherent in all; easygoing retain guarantee, strivers can superimpose higher; infinite origin eliminates predation motive</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The Saiyan setting is Dragon Ball worldview&#39;s deepest and most dangerous setting — it writes &quot;predation&quot; into a race&#39;s biological instinct. Goku is not a bad person, but he lives in a &quot;battle = predation&quot; system without knowing. Heng Yuan Zhou&#39;s answer: Saiyans&#39; combat talent can be retained, but must be redirected to guarding Myriad Ranks, not conquering planets; near-death gain can be retained, but must be made safe and technological, not betting lives. Let the warrior race from predators become guardians; this is the Saiyan setting&#39;s true redemption.</p><p>In the final analysis, Dragon Ball · Saiyan setting · the predatory essence of a warrior race described in this document is no isolated case — its causality and energy-level traces are filed throughout in the Alaya Network, traceable and verifiable.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Related documents: <a href="./459_模块2-龙珠-地球设定分析-文明建设的极度缺失.html">Entry 459 · Earth Setting</a> · <a href="./461_模块2-龙珠-弗利萨军团-掠夺式文明的极端形态.html">Entry 461 · Frieza Army</a> · <a href="./../wanling-hengmao-origin-universe-archive/docs/zh/04-反掠夺主义核心论纲.html">04-Anti-Predation Core Thesis</a></li><li>Official site: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',28)])])}const y=t(o,[["render",r]]);export{g as __pageData,y as default};
